import { expect, expectStatus, test, type Document } from "../../fixtures";

test("a vendor with only an extracted W-9 can't be submitted yet", { tag: "@UI-08" }, async ({ pages, signIn, factory, apiAs }) => {
  // Arrange
  const vendor = await factory.vendor();
  await factory.upload(vendor.id, "w9");
  const member = await apiAs("member");
  await expect
    .poll(
      async () => {
        const documents = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
        return documents.map((d) => d.status);
      },
      { message: "the W-9 finishes extraction", timeout: 30_000 },
    )
    .toEqual(["extracted"]);
  await signIn("member");

  // Act
  await pages.vendor.goto(vendor.id);

  // Assert
  await expect(pages.vendor.submitButton).toBeDisabled();
  await expect(pages.vendor.stillNeeded(["insurance_certificate", "contract"])).toBeVisible();
});
